package com.ghordrin.bosshealthbar;

import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.SpriteID;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class KnownBossesTest
{
	@Test
	public void matchesListedBossesIgnoringCase()
	{
		assertTrue(KnownBosses.contains("Zulrah"));
		assertTrue(KnownBosses.contains("zulrah"));
		assertTrue(KnownBosses.contains("K'RIL TSUTSAROTH"));
	}

	@Test
	public void rejectsOtherNamesAndNull()
	{
		assertFalse(KnownBosses.contains("Mithril dragon"));
		assertFalse(KnownBosses.contains(""));
		assertFalse(KnownBosses.contains(null));
	}

	@Test
	public void bossesUseTheirHiscoreIcon()
	{
		assertEquals(new KnownBosses.Icon(false, SpriteID.IconBoss25x25.ZULRAH), KnownBosses.icon("Zulrah"));
		assertEquals(new KnownBosses.Icon(false, SpriteID.IconBoss25x25.GROTESQUE_GUARDIANS), KnownBosses.icon("dawn"));
	}

	@Test
	public void raidBossesUseTheirPet()
	{
		assertEquals(new KnownBosses.Icon(true, ItemID.TEKTONPET), KnownBosses.icon("Tekton"));
		assertEquals(new KnownBosses.Icon(true, ItemID.VERZIKPET), KnownBosses.icon("Verzik Vitur"));
		assertEquals(new KnownBosses.Icon(true, ItemID.TEKTONENRAGEDPET), KnownBosses.icon("Tekton (enraged)"));
	}

	@Test
	public void bossesWithoutAnIconAreStillKnown()
	{
		assertTrue(KnownBosses.contains("Ice demon"));
		assertNull(KnownBosses.icon("Ice demon"));
		assertNotNull(KnownBosses.colors("Ice demon"));
	}

	@Test
	public void ignoresColorTagsInNames()
	{
		assertTrue(KnownBosses.contains("<col=00ffff>Guardian</col>"));
		assertNotNull(KnownBosses.colors("<col=00ffff>Guardian</col>"));
	}

	@Test
	public void otherNamesHaveNoIcon()
	{
		assertNull(KnownBosses.icon("Mithril dragon"));
		assertNull(KnownBosses.icon(null));
	}

	@Test
	public void everyFormOfABossSharesItsColors()
	{
		assertSame(KnownBosses.colors("Tekton"), KnownBosses.colors("Tekton (enraged)"));
		assertSame(KnownBosses.colors("Doom of Mokhaiotl"), KnownBosses.colors("Doom of Mokhaiotl (Burrowed)"));
		assertSame(KnownBosses.colors("Great Olm"), KnownBosses.colors("Great Olm (Left claw)"));
		assertSame(KnownBosses.colors("Dagannoth Rex"), KnownBosses.colors("Dagannoth Prime"));
	}

	@Test
	public void godAlignedBossesUseTheirTheme()
	{
		assertSame(HealthBarTheme.ZAMORAK.getColors(), KnownBosses.colors("K'ril Tsutsaroth"));
		assertSame(HealthBarTheme.TUMEKEN.getColors(), KnownBosses.colors("Tumeken's Warden"));
	}

	@Test
	public void otherNamesHaveNoColors()
	{
		assertNotNull(KnownBosses.colors("vorkath"));
		assertNull(KnownBosses.colors("Mithril dragon"));
		assertNull(KnownBosses.colors(null));
	}
}

package com.ghordrin.bosshealthbar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class NativeBossBarModeTest
{
	@Test
	public void oldCheckboxMapsToTheMatchingMode()
	{
		assertEquals(NativeBossBarMode.REPLACE, NativeBossBarMode.fromReplaceSetting("true"));
		assertEquals(NativeBossBarMode.HIDE_OURS, NativeBossBarMode.fromReplaceSetting("false"));
		assertNull(NativeBossBarMode.fromReplaceSetting(null));
	}

	@Test
	public void migrationOverridesTheSavedDefaultButNotAnotherChoice()
	{
		assertEquals(NativeBossBarMode.HIDE_OURS, NativeBossBarMode.migrate("false", "REPLACE"));
		assertEquals(NativeBossBarMode.HIDE_OURS, NativeBossBarMode.migrate("false", null));
		assertEquals(NativeBossBarMode.REPLACE, NativeBossBarMode.migrate("true", "REPLACE"));
		assertNull(NativeBossBarMode.migrate("false", "BOTH"));
		assertNull(NativeBossBarMode.migrate("true", "HIDE_OURS"));
		assertNull(NativeBossBarMode.migrate(null, "REPLACE"));
	}

	@Test
	public void onlyReplaceHidesTheGameBarAndOnlyHideOursHidesOurs()
	{
		assertTrue(NativeBossBarMode.REPLACE.hidesGameBar());
		assertFalse(NativeBossBarMode.REPLACE.hidesOurBar());
		assertFalse(NativeBossBarMode.BOTH.hidesGameBar());
		assertFalse(NativeBossBarMode.BOTH.hidesOurBar());
		assertFalse(NativeBossBarMode.HIDE_OURS.hidesGameBar());
		assertTrue(NativeBossBarMode.HIDE_OURS.hidesOurBar());
	}
}

package com.ghordrin.bosshealthbar;

import static com.ghordrin.bosshealthbar.DamageTracker.COMBO_WINDOW;
import static com.ghordrin.bosshealthbar.DamageTracker.countsTowardCombo;
import static com.ghordrin.bosshealthbar.DamageTracker.nextComboDamage;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class DamageTrackerTest
{
	private static final long WINDOW_MILLIS = COMBO_WINDOW.toMillis();

	@Test
	public void firstHitStartsTheCombo()
	{
		assertEquals(50, nextComboDamage(0, 0, 1_000, 50));
	}

	@Test
	public void hitsWithinTheWindowAddUp()
	{
		final int afterFirstHit = nextComboDamage(0, 0, 1_000, 50);
		final int afterSecondHit = nextComboDamage(afterFirstHit, 1_000, 1_000 + WINDOW_MILLIS - 1, 30);

		assertEquals(80, afterSecondHit);
	}

	@Test
	public void aHitRightAtTheWindowEdgeStillCounts()
	{
		assertEquals(80, nextComboDamage(50, 1_000, 1_000 + WINDOW_MILLIS, 30));
	}

	@Test
	public void aHitPastTheWindowStartsAFreshCombo()
	{
		assertEquals(30, nextComboDamage(50, 1_000, 1_000 + WINDOW_MILLIS + 1, 30));
	}

	@Test
	public void aStalePreviousComboIsIgnoredWhenThereWasNoRecentHit()
	{
		assertEquals(10, nextComboDamage(999, 0, 5_000, 10));
	}

	@Test
	public void yourOwnHitsAlwaysCount()
	{
		for (DamageNumberSource source : DamageNumberSource.values())
		{
			assertTrue(source.toString(), countsTowardCombo(true, false, source));
		}
	}

	@Test
	public void onlyEveryoneCountsOtherPlayersHitsplats()
	{
		assertFalse(countsTowardCombo(false, true, DamageNumberSource.ME));
		assertFalse(countsTowardCombo(false, true, DamageNumberSource.PARTY));
		assertTrue(countsTowardCombo(false, true, DamageNumberSource.EVERYONE));
		assertFalse(countsTowardCombo(false, false, DamageNumberSource.EVERYONE));
	}

	@Test
	public void partyHitsAddToTheCombo()
	{
		final DamageTracker tracker = new DamageTracker();
		tracker.recordPartyHit(20);
		tracker.recordPartyHit(15);
		tracker.recordPartyHit(0);

		assertEquals(35, tracker.getComboDamage());
	}
}

package com.ghordrin.bosshealthbar;

import java.util.HashMap;
import java.util.Map;
import static com.ghordrin.bosshealthbar.BossStats.Element.AIR;
import static com.ghordrin.bosshealthbar.BossStats.Element.EARTH;
import static com.ghordrin.bosshealthbar.BossStats.Element.FIRE;
import static com.ghordrin.bosshealthbar.BossStats.Element.WATER;
import net.runelite.api.gameval.ItemID;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class BossStatsTest
{
	@Test
	public void looksUpWeaknessByNpcId()
	{
		assertEquals(new BossStats.Weakness(BossStats.Element.FIRE, 50), BossStats.weakness(2042));
		assertEquals(new BossStats.Weakness(BossStats.Element.FIRE, 50), BossStats.weakness(2044));
		assertEquals(new BossStats.Weakness(BossStats.Element.WATER, 40), BossStats.weakness(5862));
		assertEquals(new BossStats.Weakness(BossStats.Element.EARTH, 10), BossStats.weakness(319));
		assertEquals(new BossStats.Weakness(BossStats.Element.AIR, 65), BossStats.weakness(12082));
	}

	@Test
	public void formsOfOneBossCanDiffer()
	{
		assertEquals(35, BossStats.weakness(11721).getPercent());
		assertEquals(40, BossStats.weakness(11719).getPercent());
		assertEquals(50, BossStats.drainCap(10864).intValue());
		assertEquals(100, BossStats.drainCap(10867).intValue());
	}

	@Test
	public void looksUpDrainCapByNpcId()
	{
		assertEquals(10, BossStats.drainCap(11789).intValue());
		assertEquals(10, BossStats.drainCap(11796).intValue());
		assertEquals(30, BossStats.drainCap(9460).intValue());
		assertEquals(80, BossStats.drainCap(14176).intValue());
	}

	@Test
	public void bossesThatCantBeDrainedHaveACapOfZero()
	{
		assertEquals(0, BossStats.drainCap(8369).intValue());
		assertEquals(0, BossStats.drainCap(10853).intValue());
		assertEquals("no drain", BossStats.drainCapText(BossStats.drainCap(8370)));
	}

	@Test
	public void unknownIdsHaveNoStats()
	{
		assertNull(BossStats.weakness(1));
		assertNull(BossStats.drainCap(1));
		assertNull(BossStats.weakness(-1));
		assertNull(BossStats.drainCap(-1));
		assertNull(BossStats.drainCap(2042));
	}

	@Test
	public void statesWithoutAWeaknessCanStillHaveACap()
	{
		assertNull(BossStats.weakness(11720));
