package com.ghordrin.bosshealthbar;

import java.util.Arrays;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

@Singleton
class GameBossBar
{
	// Set to 1 on NPCs whose game boss bar only shows a percentage. No gameval constant exists for it.
	private static final int PARAM_HP_PERCENTAGE_ONLY = 2289;

	private static final int[] PHASE_MARKER_VARBITS = {
		VarbitID.HPBAR_HUD_LOWER_THRESHOLD,
		VarbitID.HPBAR_HUD_UPPER_THRESHOLD,
		VarbitID.HPBAR_HUD_HP_1,
		VarbitID.HPBAR_HUD_HP_2,
	};

	private final Client client;

	private boolean hidden;
	private NPC npc;
	private int searchedId = -1;
	private int replacedId = -1;

	private int percentOnlyNpcId = -1;
	private boolean percentOnly;

	private final int[] phaseMarkerValues = new int[PHASE_MARKER_VARBITS.length];
	private int phaseMarkerMaxHealth;
	private float[] phaseMarkers = BarState.NO_PHASE_MARKERS;

	@Inject
	GameBossBar(Client client)
	{
		this.client = client;
	}

	int trackedNpcId()
	{
		if (client.getVarbitValue(VarbitID.HPBAR_HUD_BOSS_DISABLED) != 0)
		{
			return -1;
		}
		return client.getVarpValue(VarPlayerID.HPBAR_HUD_NPC);
	}

	boolean isTracking(Actor actor)
	{
		if (!(actor instanceof NPC))
		{
			return false;
		}
		final int trackedId = trackedNpcId();
		return trackedId != -1 && NpcUtil.baseId((NPC) actor) == trackedId;
	}

	NPC findNpc(Actor opponent)
	{
		final int trackedId = trackedNpcId();
		if (trackedId == -1)
		{
			npc = null;
			searchedId = -1;
			return null;
		}

		if (isTracking(opponent))
		{
			npc = (NPC) opponent;
			return npc;
		}

		final Player player = client.getLocalPlayer();
		final Actor target = player != null ? player.getInteracting() : null;
		if (isTracking(target))
		{
			npc = (NPC) target;
			return npc;
		}

		if (npc != null && NpcUtil.baseId(npc) == trackedId)
		{
			return npc;
		}

		if (npc == null && trackedId == searchedId)
		{
			return null;
		}

		npc = null;
		searchedId = trackedId;
		for (NPC candidate : client.getTopLevelWorldView().npcs())
		{
			if (NpcUtil.baseId(candidate) == trackedId)
			{
				npc = candidate;
				break;
			}
		}
		return npc;
	}

	void onNpcSpawned()
	{
		searchedId = -1;
	}

	void onNpcDespawned(NPC despawned)
	{
		if (despawned == npc)
		{
			npc = null;
		}
	}

	void update(Actor opponent, boolean replaceEnabled, boolean opponentGetsBar)
	{
		final Widget bar = client.getWidget(InterfaceID.HpbarHud.UNIVERSE);
		if (bar == null)
		{
			hidden = false;
			return;
		}

		boolean replace = false;
		if (replaceEnabled)
		{
			if (opponentGetsBar && isTracking(opponent))
			{
				replace = true;
				replacedId = trackedNpcId();
			}
			else
			{
				// After the boss despawns, the game's bar can stay up on it while the defeat animation
				// plays, so keep it hidden until it tracks a different NPC.
				replace = replacedId != -1 && trackedNpcId() == replacedId;
			}
		}

		if (replace)
		{
			if (!bar.isSelfHidden())
			{
				bar.setHidden(true);
				hidden = true;
			}
		}
		else
		{
			replacedId = -1;
			restore();
		}
	}

	void restore()
	{
		if (!hidden || trackedNpcId() == -1)
		{
			return;
		}

		final Widget bar = client.getWidget(InterfaceID.HpbarHud.UNIVERSE);
		if (bar != null)
		{
			bar.setHidden(false);
		}
		hidden = false;
	}

	void reset()
	{
		hidden = false;
		npc = null;
		searchedId = -1;
		replacedId = -1;
	}

	int maxHealth()
	{
		return client.getVarbitValue(VarbitID.HPBAR_HUD_BASEHP);
	}

	int health()
	{
		return client.getVarbitValue(VarbitID.HPBAR_HUD_HP);
	}

	boolean isPercentOnly()
	{
		final int npcId = client.getVarpValue(VarPlayerID.HPBAR_HUD_NPC);
		if (npcId != percentOnlyNpcId)
		{
			final NPCComposition composition = npcId != -1 ? client.getNpcDefinition(npcId) : null;
			percentOnly = composition != null && composition.getIntValue(PARAM_HP_PERCENTAGE_ONLY) == 1;
			percentOnlyNpcId = npcId;
		}
		return percentOnly;
	}

	float[] phaseMarkers(int maxHealth)
	{
		boolean changed = maxHealth != phaseMarkerMaxHealth;
		for (int i = 0; i < PHASE_MARKER_VARBITS.length; i++)
		{
			final int value = client.getVarbitValue(PHASE_MARKER_VARBITS[i]);
			if (value != phaseMarkerValues[i])
			{
				phaseMarkerValues[i] = value;
				changed = true;
			}
		}
		if (!changed)
		{
			return phaseMarkers;
		}
		phaseMarkerMaxHealth = maxHealth;

		float[] markers = null;
		int count = 0;
		for (int value : phaseMarkerValues)
		{
			if (value > 0 && value <= maxHealth + 1)
			{
				if (markers == null)
				{
					markers = new float[PHASE_MARKER_VARBITS.length];
				}
				markers[count++] = markerFraction(value, maxHealth);
			}
		}
		phaseMarkers = markers == null ? BarState.NO_PHASE_MARKERS : Arrays.copyOf(markers, count);
		return phaseMarkers;
	}

	// Same placement as the game's own bar: a marker for value v sits at (v - 1) / max health.
	static float markerFraction(int value, int maxHealth)
	{
		return BarAnimation.clamp01((value - 1) / (float) maxHealth);
	}
}

package com.ghordrin.bosshealthbar;

import com.google.common.annotations.VisibleForTesting;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.ui.overlay.infobox.InfoBox;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;

// Reads the counts RuneLite's "Special Attack Counter" plugin shows in its info boxes, one per weapon.
@Slf4j
@Singleton
class SpecialAttackCounts
{
	private static final String PLUGIN_NAME = "Special Attack Counter";
	// InfoBox.getName() defaults to the plugin's class name and the info box's class name.
	@VisibleForTesting
	static final String BOX_NAME = "SpecialCounterPlugin_SpecialCounter";

	@Value
	static class Reading
	{
		BufferedImage image;
		String text;
		Color color;
	}

	private final BossHealthBarConfig config;
	private final PluginManager pluginManager;
	private final InfoBoxManager infoBoxManager;

	private Boolean pluginActive;
	private boolean available;
	private List<Reading> readings = Collections.emptyList();
	private boolean missedTick;

	@Inject
	SpecialAttackCounts(BossHealthBarConfig config, PluginManager pluginManager, InfoBoxManager infoBoxManager)
	{
		this.config = config;
		this.pluginManager = pluginManager;
		this.infoBoxManager = infoBoxManager;
	}

	void invalidatePlugin()
	{
		pluginActive = null;
	}

	void reset()
	{
		pluginActive = null;
		available = false;
		clear();
	}

	private void clear()
	{
		readings = Collections.emptyList();
		missedTick = false;
	}

	// Called each game tick, so the overlay doesn't go through the info boxes every frame.
	void update(Actor opponent)
	{
		if (pluginActive == null)
		{
			pluginActive = isPluginActive();
		}
		available = pluginActive && config.showSpecialAttackCounts();

		if (!available || opponent == null)
		{
			clear();
			return;
		}

		try
		{
			accept(find(infoBoxManager.getInfoBoxes()));
		}
		catch (RuntimeException e)
		{
			log.debug("Couldn't read Special Attack Counter info boxes", e);
			clear();
		}
	}

	// Their info boxes can be gone for a tick while they're rebuilt, so the last readings are kept for one tick.
	@VisibleForTesting
	void accept(List<Reading> found)
	{
		if (!found.isEmpty())
		{
			if (!found.equals(readings))
			{
				readings = found;
			}
			missedTick = false;
		}
		else if (!readings.isEmpty() && !missedTick)
		{
			missedTick = true;
		}
		else
		{
			clear();
		}
	}

	boolean isAvailable()
	{
		return available;
	}

	List<Reading> readings()
	{
		return readings;
	}

	private boolean isPluginActive()
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (PLUGIN_NAME.equals(plugin.getName()))
			{
				return pluginManager.isPluginActive(plugin);
			}
		}
		return false;
	}

	@VisibleForTesting
	static List<Reading> find(List<InfoBox> infoBoxes)
	{
		List<Reading> found = null;
		for (InfoBox infoBox : infoBoxes)
		{
			if (!matches(infoBox))
			{
				continue;
			}
			final String text = infoBox.getText();
			if (text == null || text.isEmpty())
			{
				continue;
			}
			if (found == null)
			{
				found = new ArrayList<>();
			}
			found.add(new Reading(infoBox.getImage(), text, infoBox.getTextColor()));
		}
		return found != null ? Collections.unmodifiableList(found) : Collections.emptyList();
	}

	@VisibleForTesting
	static boolean matches(InfoBox infoBox)
	{
		return infoBox != null && BOX_NAME.equals(infoBox.getName());
	}
}

package com.ghordrin.bosshealthbar;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.InteractingChanged;

@Slf4j
@Singleton
class OpponentTracker
{
	// Past the longest attack range, with room to reposition, but close enough that walking away counts.
	private static final int COMBAT_DISTANCE = 15;

	private final Client client;
	private final BossHealthBarConfig config;
	private final GameBossBar gameBossBar;
	private final TobBossBar tobBossBar;
	private final SuperiorTracker superiors;
	private final DamageTracker damage;

	@Getter(AccessLevel.PACKAGE)
	private Actor opponent;
	private long interactionLostMillis;
	private long lastHitTakenMillis;
	private long lastOpponentHitMillis;

	private Actor knownBossActor;
	private String knownBossName;
	private boolean knownBoss;

	@Inject
	OpponentTracker(Client client, BossHealthBarConfig config, GameBossBar gameBossBar, TobBossBar tobBossBar,
		SuperiorTracker superiors, DamageTracker damage)
	{
		this.client = client;
		this.config = config;
		this.gameBossBar = gameBossBar;
		this.tobBossBar = tobBossBar;
		this.superiors = superiors;
		this.damage = damage;
	}

	void onInteractingChanged(InteractingChanged event)
	{
		if (event.getSource() != client.getLocalPlayer())
		{
			return;
		}

		final Actor target = event.getTarget();
		if (target == null)
		{
			interactionLostMillis = System.currentTimeMillis();
			log.debug("Interaction lost with {}, will clear after {}s if not resumed", opponent, config.hideDelay());
			return;
		}

		interactionLostMillis = 0;

		if (target == opponent)
		{
			return;
		}

		// Attacking the smaller NPCs a boss spawns shouldn't take the bar off the boss.
		if (opponent != null && !opponent.isDead() && priority(target) < priority(opponent))
		{
			log.debug("Keeping {} over lower priority target {}", opponent.getName(), target.getName());
			return;
		}

		setOpponent(target);
	}

	// While a game boss bar is up, the bar follows the NPC it shows.
	void followGameBars()
	{
		final NPC nativeBarBoss = gameBossBar.findNpc(opponent);
		final NPC gameBarBoss = nativeBarBoss != null ? nativeBarBoss : tobBossBar.findBoss();
		if (gameBarBoss != null && !gameBarBoss.isDead() && gameBarBoss != opponent)
		{
			setOpponent(gameBarBoss);
			interactionLostMillis = 0;
		}
	}

	void onNpcDespawned(NPC npc)
	{
		if (npc != opponent)
		{
			return;
		}

		log.debug("Opponent {} despawned, clearing", opponent);
		opponent = null;
		interactionLostMillis = 0;
		lastOpponentHitMillis = 0;
		damage.resetCombo();
	}

	void onHitsplatApplied(Actor actor, Hitsplat hitsplat)
	{
		if (!isCombatHit(hitsplat.getHitsplatType()))
		{
			return;
		}
		if (actor == client.getLocalPlayer())
		{
			lastHitTakenMillis = System.currentTimeMillis();
		}
		else if (actor != null && actor == opponent)
		{
			lastOpponentHitMillis = System.currentTimeMillis();
		}
	}

	// Clears the opponent once the fight has been quiet for longer than "Hide after", unless a
	// game boss bar still shows it.
	void onGameTick()
	{
		final Player player = client.getLocalPlayer();
		if (opponent == null || player == null || interactionLostMillis == 0)
		{
			return;
		}

		final boolean nearby = !opponent.isDead()
			&& opponent.getWorldArea().distanceTo(player.getWorldLocation()) <= COMBAT_DISTANCE;

		if (opponent != gameBossBar.findNpc(opponent)
			&& opponent != tobBossBar.findBoss()
			&& player.getInteracting() == null
			&& isQuietFor(interactionLostMillis, lastHitTakenMillis, lastOpponentHitMillis, nearby,
				System.currentTimeMillis(), config.hideDelay() * 1000L))
		{
			log.debug("Opponent {} timed out after {}s with no combat, clearing", opponent, config.hideDelay());
			opponent = null;
		}
	}

	static boolean isQuietFor(long interactionLostMillis, long lastHitTakenMillis, long lastOpponentHitMillis,
		boolean nearby, long now, long delayMillis)
	{
		if (interactionLostMillis == 0)
		{
			return false;
		}
		long lastCombat = interactionLostMillis;
		if (nearby)
		{
			lastCombat = Math.max(lastCombat, Math.max(lastHitTakenMillis, lastOpponentHitMillis));
		}
		return now - lastCombat > delayMillis;
	}

	// Damage over time is left out on purpose, so ticks that linger after a fight don't keep the bar up.
	static boolean isCombatHit(int hitsplatType)
	{
		switch (hitsplatType)
		{
			case HitsplatID.BLOCK_ME:
			case HitsplatID.BLOCK_OTHER:
			case HitsplatID.DAMAGE_ME:
			case HitsplatID.DAMAGE_OTHER:
			case HitsplatID.DAMAGE_ME_CYAN:
			case HitsplatID.DAMAGE_OTHER_CYAN:
			case HitsplatID.DAMAGE_ME_ORANGE:
			case HitsplatID.DAMAGE_OTHER_ORANGE:
			case HitsplatID.DAMAGE_ME_YELLOW:
			case HitsplatID.DAMAGE_OTHER_YELLOW:
			case HitsplatID.DAMAGE_ME_WHITE:
			case HitsplatID.DAMAGE_OTHER_WHITE:
			case HitsplatID.DAMAGE_MAX_ME:
			case HitsplatID.DAMAGE_MAX_ME_CYAN:
			case HitsplatID.DAMAGE_MAX_ME_ORANGE:
			case HitsplatID.DAMAGE_MAX_ME_YELLOW:
			case HitsplatID.DAMAGE_MAX_ME_WHITE:
			case HitsplatID.DAMAGE_ME_POISE:
			case HitsplatID.DAMAGE_OTHER_POISE:
			case HitsplatID.DAMAGE_MAX_ME_POISE:
				return true;
			default:
				return false;
		}
	}

	boolean shouldShowBarFor(Actor actor)
	{
		return actor != null
			&& actor.getName() != null
			&& (!config.bossOnly()
				|| isKnownBoss(actor)
				|| isGameBarBoss(actor)
				|| (config.showAboveCombatLevel() && actor.getCombatLevel() >= config.minimumCombatLevel())
				|| (config.showSuperiors() && superiors.isSuperior(actor)));
	}

	void reset()
	{
		opponent = null;
		interactionLostMillis = 0;
		lastHitTakenMillis = 0;
		lastOpponentHitMillis = 0;
		knownBossActor = null;
		knownBossName = null;
	}

	private void setOpponent(Actor target)
	{
		damage.resetCombo();
		opponent = target;
		lastOpponentHitMillis = 0;
		log.debug("New opponent: {} (combat level {}, known boss: {}, game boss bar: {})",
			target.getName(), target.getCombatLevel(), KnownBosses.contains(target.getName()), isGameBarBoss(target));
	}

	private int priority(Actor actor)
	{
		if (actor == null)
		{
			return -1;
		}
		if (gameBossBar.isTracking(actor) || tobBossBar.isTracking(actor))
		{
			return 2;
		}
		return shouldShowBarFor(actor) ? 1 : 0;
	}

	private boolean isGameBarBoss(Actor actor)
	{
		return actor != null && (gameBossBar.isTracking(actor) || actor == tobBossBar.cachedBoss());
	}

	// Checked every frame, so the answer is kept for the last actor and name.
	private boolean isKnownBoss(Actor actor)
	{
		final String name = actor.getName();
		if (actor != knownBossActor || !name.equals(knownBossName))
		{
			knownBossActor = actor;
			knownBossName = name;
			knownBoss = KnownBosses.contains(name);
		}
		return knownBoss;
	}
}

package com.ghordrin.bosshealthbar;

import java.time.Duration;
import javax.inject.Singleton;
import lombok.AccessLevel;
import lombok.Getter;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;

@Singleton
class DamageTracker
{
	static final Duration COMBO_WINDOW = Duration.ofMillis(2500);

	@Getter(AccessLevel.PACKAGE)
	private long lastHitMillis;

	@Getter(AccessLevel.PACKAGE)
	private int lastHitAmount;

	@Getter(AccessLevel.PACKAGE)
	private int comboDamage;

	@Getter(AccessLevel.PACKAGE)
	private long lastDamageDealtMillis;

	void recordHit(Hitsplat hitsplat, DamageNumberSource source)
	{
		if (hitsplat.getAmount() <= 0 || hitsplat.getHitsplatType() == HitsplatID.HEAL)
		{
			return;
		}

		final long now = System.currentTimeMillis();
		lastHitMillis = now;
		lastHitAmount = hitsplat.getAmount();

		if (countsTowardCombo(hitsplat.isMine(), hitsplat.isOthers(), source))
		{
			addToCombo(hitsplat.getAmount(), now);
		}
	}

	// Party members' hits arrive over the party connection instead, so their hitsplats aren't counted twice.
	static boolean countsTowardCombo(boolean mine, boolean others, DamageNumberSource source)
	{
		return mine || (others && source == DamageNumberSource.EVERYONE);
	}

	void recordPartyHit(int amount)
	{
		if (amount > 0)
		{
			addToCombo(amount, System.currentTimeMillis());
		}
	}

	private void addToCombo(int amount, long now)
	{
		comboDamage = nextComboDamage(comboDamage, lastDamageDealtMillis, now, amount);
		lastDamageDealtMillis = now;
	}

	void resetCombo()
	{
		comboDamage = 0;
		lastDamageDealtMillis = 0;
	}

	void reset()
	{
		lastHitMillis = 0;
		resetCombo();
	}

	static int nextComboDamage(int previousCombo, long previousDamageMillis, long now, int hitAmount)
	{
		final boolean withinWindow = previousDamageMillis != 0 && now - previousDamageMillis <= COMBO_WINDOW.toMillis();
		return (withinWindow ? previousCombo : 0) + hitAmount;
	}
}

package com.ghordrin.bosshealthbar;

import com.google.common.annotations.VisibleForTesting;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.ui.overlay.infobox.InfoBox;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;
import net.runelite.client.util.Text;

// Reads the defence the "Party Defence Tracker" plugin shows in its info box for the current opponent.
@Slf4j
@Singleton
class PartyDefence
{
	private static final String PLUGIN_NAME = "Party Defence Tracker";
	// InfoBox.getName() defaults to the plugin's class name and the info box's class name.
	@VisibleForTesting
	static final String BOX_NAME = "DefenceTrackerPlugin_DefenceInfoBox";

	@Value
	static class Reading
	{
		String text;
		Color color;
	}

	private final BossHealthBarConfig config;
	private final PluginManager pluginManager;
	private final InfoBoxManager infoBoxManager;
	private final SkillIconManager skillIconManager;

	private Boolean pluginActive;
	private boolean available;
	private String readingName;
	private Reading reading;
	private boolean missedTick;
	private BufferedImage icon;

	@Inject
	PartyDefence(BossHealthBarConfig config, PluginManager pluginManager, InfoBoxManager infoBoxManager,
		SkillIconManager skillIconManager)
	{
		this.config = config;
		this.pluginManager = pluginManager;
		this.infoBoxManager = infoBoxManager;
		this.skillIconManager = skillIconManager;
	}

	void invalidatePlugin()
	{
		pluginActive = null;
	}

	void reset()
	{
		pluginActive = null;
		available = false;
		clear();
	}

	private void clear()
	{
		readingName = null;
		reading = null;
		missedTick = false;
	}

	// Called each game tick, so the overlay doesn't go through the info boxes every frame.
	void update(Actor opponent)
	{
		if (pluginActive == null)
		{
			pluginActive = isPluginActive();
		}
		available = pluginActive && config.showPartyDefence();

		final String name = opponent != null ? opponent.getName() : null;
		if (!available || name == null)
		{
			clear();
			return;
		}

		try
		{
			accept(name, find(infoBoxManager.getInfoBoxes(), name));
		}
		catch (RuntimeException e)
		{
			log.debug("Couldn't read Party Defence Tracker info box", e);
			clear();
		}
	}

	// Their info box can be gone for a tick while it's rebuilt, so the last reading is kept for one tick.
	@VisibleForTesting
	void accept(String name, Reading found)
	{
		if (found != null)
		{
			readingName = name;
			reading = found;
			missedTick = false;
		}
		else if (reading != null && !missedTick && Objects.equals(name, readingName))
		{
			missedTick = true;
		}
		else
		{
			clear();
		}
	}

	boolean isAvailable()
	{
		return available;
	}

	Reading readingFor(Actor opponent)
	{
		return opponent != null ? readingFor(opponent.getName()) : null;
	}

	@VisibleForTesting
	Reading readingFor(String name)
	{
		return name != null && name.equals(readingName) ? reading : null;
	}

	BufferedImage icon()
	{
		if (icon == null)
		{
			icon = skillIconManager.getSkillImage(Skill.DEFENCE, true);
		}
		return icon;
	}

	private boolean isPluginActive()
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (PLUGIN_NAME.equals(plugin.getName()))
			{
				return pluginManager.isPluginActive(plugin);
			}
		}
		return false;
	}

	@VisibleForTesting
	static Reading find(List<InfoBox> infoBoxes, String opponentName)
	{
		for (InfoBox infoBox : infoBoxes)
		{
			if (!matches(infoBox, opponentName))
			{
				continue;
			}
			final String text = infoBox.getText();
			if (text != null && !text.isEmpty())
			{
				return new Reading(text, infoBox.getTextColor());
			}
		}
		return null;
	}

	@VisibleForTesting
	static boolean matches(InfoBox infoBox, String opponentName)
	{
		if (infoBox == null || opponentName == null || !BOX_NAME.equals(infoBox.getName()))
		{
			return false;
		}
		final String tooltip = infoBox.getTooltip();
		return tooltip != null && Text.removeTags(tooltip).trim().equalsIgnoreCase(Text.removeTags(opponentName).trim());
	}
}

