			NpcID.VERZIK_PHASE2_TO3_TRANSITION_HARD, NpcID.VERZIK_PHASE3_HARD, NpcID.VERZIK_DEATH_BAT_HARD);

	private static final Map<Integer, Weakness> WEAKNESSES = TABLE.weaknesses.build();
	private static final Map<Integer, Integer> DRAIN_CAPS = TABLE.drainCaps.build();

	private BossStats()
	{
	}

	static Weakness weakness(int npcId)
	{
		return WEAKNESSES.get(npcId);
	}

	static Integer drainCap(int npcId)
	{
		return DRAIN_CAPS.get(npcId);
	}

	static Info info(int npcId)
	{
		final Weakness weakness = weakness(npcId);
		final Integer drainCap = drainCap(npcId);
		if (weakness == null && drainCap == null)
		{
			return null;
		}
		return new Info(weakness != null ? weakness.getElement() : null, weaknessText(weakness), drainCapText(drainCap));
	}

	static String weaknessText(Weakness weakness)
	{
		return weakness != null ? "+" + weakness.getPercent() + "%" : null;
	}

	static String drainCapText(Integer cap)
	{
		if (cap == null)
		{
			return null;
		}
		return cap > 0 ? "-" + cap : "no drain";
	}

	private static final class Builder
	{
		private final ImmutableMap.Builder<Integer, Weakness> weaknesses = ImmutableMap.builder();
		private final ImmutableMap.Builder<Integer, Integer> drainCaps = ImmutableMap.builder();

		Builder weakness(Element element, int percent, int... npcIds)
		{
			final Weakness weakness = new Weakness(element, percent);
			for (int npcId : npcIds)
			{
				weaknesses.put(npcId, weakness);
			}
			return this;
		}

		Builder drainCap(int cap, int... npcIds)
		{
			for (int npcId : npcIds)
			{
				drainCaps.put(npcId, cap);
			}
			return this;
		}
	}
}

package com.ghordrin.bosshealthbar;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

@Singleton
class TobBossBar
{
	// Values of TOB_CLIENT_WAVEPROGRESS_TYPE. Other values show room progress instead of health.
	private static final int PROGRESS_NONE = 0;
	private static final int PROGRESS_BOSS_HEALTH = 1;
	private static final int SEARCH_DISTANCE = 32;

	private final Client client;

	private boolean hidden;
	private NPC boss;
	private boolean searchNeeded = true;

	@Inject
	TobBossBar(Client client)
	{
		this.client = client;
	}

	// The Theatre of Blood bar doesn't say which NPC it belongs to, so this takes the highest level
	// attackable NPC nearby. Cached until a stronger NPC spawns or the boss changes or despawns.
	NPC findBoss()
	{
		if (client.getVarbitValue(VarbitID.TOB_CLIENT_WAVEPROGRESS_TYPE) != PROGRESS_BOSS_HEALTH
			|| client.getWidget(InterfaceID.TobHud.PROGRESS_CONTAINER) == null)
		{
			boss = null;
			searchNeeded = true;
			return null;
		}

		if (!searchNeeded)
		{
			return boss;
		}

		searchNeeded = false;
		boss = null;
		final Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}

		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			if (npc.isDead() || !NpcUtil.isAttackable(npc)
				|| npc.getWorldLocation().distanceTo(player.getWorldLocation()) > SEARCH_DISTANCE)
			{
				continue;
			}

			if (boss == null
				|| npc.getCombatLevel() > boss.getCombatLevel()
				|| (npc.getCombatLevel() == boss.getCombatLevel() && NpcUtil.size(npc) > NpcUtil.size(boss)))
			{
				boss = npc;
			}
		}
		return boss;
	}

	// The last boss found, without searching again.
	NPC cachedBoss()
	{
		return boss;
	}

	boolean isTracking(Actor actor)
	{
		return actor != null && actor == findBoss();
	}

	void onNpcSpawned(NPC npc)
	{
		if (mayBeBoss(npc))
		{
			searchNeeded = true;
		}
	}

	void onNpcChanged(NPC npc)
	{
		if (npc == boss || mayBeBoss(npc))
		{
			searchNeeded = true;
		}
	}

	void onNpcDespawned(NPC npc)
	{
		if (npc == boss)
		{
			boss = null;
			searchNeeded = true;
		}
	}

	void onGameTick()
	{
		if (boss == null)
		{
			// The room's boss may only have come into range as the player walked in.
			searchNeeded = true;
		}
	}

	private boolean mayBeBoss(NPC npc)
	{
		return boss == null || npc.getCombatLevel() >= boss.getCombatLevel();
	}

	void update(Actor opponent, boolean replaceEnabled, boolean opponentGetsBar)
	{
		final Widget bar = client.getWidget(InterfaceID.TobHud.PROGRESS_CONTAINER);
		if (bar == null)
		{
			hidden = false;
			return;
		}

		if (replaceEnabled && isTracking(opponent) && opponentGetsBar)
		{
			if (!bar.isSelfHidden())
			{
				bar.setHidden(true);
				hidden = true;
			}
		}
		else
		{
			restore();
		}
	}

	void restore()
	{
		if (!hidden)
		{
			return;
		}

		final Widget bar = client.getWidget(InterfaceID.TobHud.PROGRESS_CONTAINER);
		if (bar != null && client.getVarbitValue(VarbitID.TOB_CLIENT_WAVEPROGRESS_TYPE) != PROGRESS_NONE)
		{
			bar.setHidden(false);
		}
		hidden = false;
	}

	void reset()
	{
		hidden = false;
		boss = null;
		searchNeeded = true;
	}

	int maxHealth()
	{
		return client.getVarbitValue(VarbitID.TOB_CLIENT_WAVEPROGRESS_MAX);
	}

	int health(int maxHealth)
	{
		return Math.max(0, Math.min(maxHealth, client.getVarbitValue(VarbitID.TOB_CLIENT_WAVEPROGRESS_VAL)));
	}
}

package com.ghordrin.bosshealthbar;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;

@Slf4j
@Singleton
class SuperiorTracker
{
	private static final String SPAWN_MESSAGE = "A superior foe has appeared";
	private static final int MATCH_TICKS = 2;
	private static final int SEARCH_DISTANCE = 15;

	private final Client client;
	private final Map<NPC, Integer> recentSpawnTicks = new HashMap<>();
	private final Set<NPC> superiors = new HashSet<>();
	private int messageTick = -1;

	@Inject
	SuperiorTracker(Client client)
	{
		this.client = client;
	}

	boolean isSuperior(Actor actor)
	{
		return superiors.contains(actor);
	}

	void onNpcSpawned(NPC npc)
	{
		recentSpawnTicks.put(npc, client.getTickCount());
	}

	void onNpcDespawned(NPC npc)
	{
		recentSpawnTicks.remove(npc);
		superiors.remove(npc);
	}

	void onChatMessage(ChatMessage event)
	{
		if ((event.getType() == ChatMessageType.GAMEMESSAGE || event.getType() == ChatMessageType.SPAM)
			&& event.getMessage().contains(SPAWN_MESSAGE))
		{
			messageTick = client.getTickCount();
			log.debug("Superior spawn message on tick {}", messageTick);
		}
	}

	// The game only announces a superior in chat, so pick the attackable NPC that spawned closest to
	// the player around the same tick. The spawn and the message can arrive in either order.
	void onGameTick()
	{
		final int tick = client.getTickCount();
		recentSpawnTicks.values().removeIf(spawnTick -> tick - spawnTick > MATCH_TICKS);

		if (messageTick == -1)
		{
			return;
		}

		final Player player = client.getLocalPlayer();
		NPC nearest = null;
		int nearestDistance = Integer.MAX_VALUE;
		if (player != null)
		{
			for (NPC npc : recentSpawnTicks.keySet())
			{
				final int distance = npc.getWorldLocation().distanceTo(player.getWorldLocation());
				if (!npc.isDead() && !superiors.contains(npc) && NpcUtil.isAttackable(npc)
					&& distance <= SEARCH_DISTANCE && distance < nearestDistance)
				{
					nearest = npc;
					nearestDistance = distance;
				}
			}
		}

		if (nearest != null)
		{
			superiors.add(nearest);
			messageTick = -1;
			log.debug("Marked {} as a superior", nearest.getName());
		}
		else if (tick - messageTick >= MATCH_TICKS)
		{
			messageTick = -1;
			log.debug("No spawned NPC found for the superior spawn message");
		}
	}

	void reset()
	{
		recentSpawnTicks.clear();
		superiors.clear();
		messageTick = -1;
	}
}

package com.ghordrin.bosshealthbar;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;

// Shares your hits on the current opponent with your RuneLite party, so members who count party
// damage can add them to their number.
@Singleton
class PartyDamage
{
	private final Client client;
	private final BossHealthBarConfig config;
	private final PartyService partyService;
	private final WSClient wsClient;
	private final OpponentTracker opponentTracker;
	private final DamageTracker damageTracker;

	@Inject
	PartyDamage(Client client, BossHealthBarConfig config, PartyService partyService, WSClient wsClient,
		OpponentTracker opponentTracker, DamageTracker damageTracker)
	{
		this.client = client;
		this.config = config;
		this.partyService = partyService;
		this.wsClient = wsClient;
		this.opponentTracker = opponentTracker;
		this.damageTracker = damageTracker;
	}

	void startUp()
	{
		wsClient.registerMessage(BossBarPartyHit.class);
	}

	void shutDown()
	{
		wsClient.unregisterMessage(BossBarPartyHit.class);
	}

	void sendHit(Actor target, int damage)
	{
		if (damage <= 0 || !(target instanceof NPC) || !partyService.isInParty())
		{
			return;
		}
		partyService.send(new BossBarPartyHit(client.getWorld(), ((NPC) target).getIndex(), damage));
	}

	void onPartyHit(BossBarPartyHit hit)
	{
		if (config.damageNumberSource() != DamageNumberSource.PARTY)
		{
			return;
		}

		final PartyMember local = partyService.getLocalMember();
		if (local != null && local.getMemberId() == hit.getMemberId())
		{
			return;
		}

		final Actor opponent = opponentTracker.getOpponent();
		if (opponent instanceof NPC && ((NPC) opponent).getIndex() == hit.getNpcIndex() && client.getWorld() == hit.getWorld())
		{
			damageTracker.recordPartyHit(hit.getDamage());
		}
	}
}

package com.ghordrin.bosshealthbar;

import java.awt.Color;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

// Fills in the Custom theme's colors from the theme that was selected before, so they can be
// tweaked from there.
@Singleton
class CustomColors
{
	private final ConfigManager configManager;

	@Inject
	CustomColors(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	// previousThemeName is the saved name of the previous theme, or null when it was the default.
	void copyFrom(String previousThemeName)
	{
		final HealthBarTheme previous = previousThemeName != null
			? HealthBarTheme.named(previousThemeName) : BossHealthBarConfig.DEFAULT_THEME;
		final ThemeColors colors = previous != null ? previous.getColors() : null;
		if (colors == null)
		{
			return;
		}

		set("customFillHighColor", colors.getFillHigh());
		set("customFillLowColor", colors.getFillLow());
		set("customTrailColor", colors.getTrail());
		set("customFrameColor", colors.getFrame());
		set("customTextColor", colors.getText());
		set("customLevelTextColor", colors.getLevelText());
		set("customHitpointsTextColor", colors.getHitpointsText());
		set("customDefeatedTextColor", colors.getDefeatedText());
	}

	private void set(String key, Color color)
	{
		configManager.setConfiguration(BossHealthBarConfig.GROUP, key, color);
	}
}

