import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;

// Reads the health lines users set up in the "Boss Health Indicators" plugin, which draws them onto the
// game's boss bar. That bar is hidden when this one replaces it, so the lines are drawn here instead.
@Slf4j
@Singleton
class HealthIndicatorMarkers
{
	static final String CONFIG_GROUP = "bosshealthindicators";
	private static final String CONFIG_KEY = "indicators";
	private static final String PLUGIN_NAME = "Boss Health Indicators";

	@Value
	static class Marker
	{
		float fraction;
		Color color;
	}

	@Value
	private static class Entry
	{
		Pattern bossName;
		List<Marker> markers;
	}

	static final Marker[] NONE = new Marker[0];

	private final BossHealthBarConfig config;
	private final ConfigManager configManager;
	private final PluginManager pluginManager;
	private final Gson gson;

	private List<Entry> entries;
	private String cachedName;
	private Marker[] cachedMarkers = NONE;

	@Inject
	HealthIndicatorMarkers(BossHealthBarConfig config, ConfigManager configManager, PluginManager pluginManager, Gson gson)
	{
		this.config = config;
		this.configManager = configManager;
		this.pluginManager = pluginManager;
		this.gson = gson;
	}

	void invalidate()
	{
		entries = null;
		cachedName = null;
	}

	// Called every frame, so the result is kept for the last name.
	Marker[] markersFor(String name)
	{
		if (name == null || !config.showHealthIndicatorMarkers())
		{
			return NONE;
		}

		if (entries == null)
		{
			entries = isPluginActive() ? parse(gson, configManager.getConfiguration(CONFIG_GROUP, CONFIG_KEY)) : Collections.emptyList();
			cachedName = null;
		}

		if (!name.equals(cachedName))
		{
			cachedName = name;
			cachedMarkers = match(entries, name);
		}
		return cachedMarkers;
	}

	private boolean isPluginActive()
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (PLUGIN_NAME.equals(plugin.getName()))
			{
				return pluginManager.isPluginActive(plugin);
			}
		}
		return false;
	}

	private static Marker[] match(List<Entry> entries, String name)
	{
		final List<Marker> matched = new ArrayList<>();
		for (Entry entry : entries)
		{
			if (entry.getBossName().matcher(name).matches())
			{
				matched.addAll(entry.getMarkers());
			}
		}
		return matched.isEmpty() ? NONE : matched.toArray(NONE);
	}

	@VisibleForTesting
	static Marker[] markersFor(Gson gson, String json, String name)
	{
		return match(parse(gson, json), name);
	}

	// The format belongs to the other plugin and could change, so anything unexpected is skipped.
	private static List<Entry> parse(Gson gson, String json)
	{
		if (json == null || json.isEmpty())
		{
			return Collections.emptyList();
		}

		final JsonElement root;
		try
		{
			root = gson.fromJson(json, JsonElement.class);
		}
		catch (JsonParseException e)
		{
			log.debug("Couldn't read Boss Health Indicators config", e);
			return Collections.emptyList();
		}
		if (root == null || !root.isJsonArray())
		{
			return Collections.emptyList();
		}

		final List<Entry> entries = new ArrayList<>();
		for (JsonElement element : root.getAsJsonArray())
		{
			final Entry entry = parseEntry(element);
			if (entry != null)
			{
				entries.add(entry);
			}
		}
		return entries;
	}

	private static Entry parseEntry(JsonElement element)
	{
		if (!element.isJsonObject())
		{
			return null;
		}
		final JsonObject object = element.getAsJsonObject();
		final String bossName = string(object.get("bossName"));
		final JsonElement markerList = object.get("entries");
		if (bossName == null || markerList == null || !markerList.isJsonArray())
		{
			return null;
		}

		final Pattern pattern;
		try
		{
			pattern = Pattern.compile(bossName);
		}
		catch (PatternSyntaxException e)
		{
			return null;
		}

		final List<Marker> markers = new ArrayList<>();
		for (JsonElement markerElement : (JsonArray) markerList)
		{
			final Marker marker = parseMarker(markerElement);
			if (marker != null)
			{
				markers.add(marker);
			}
		}
		return markers.isEmpty() ? null : new Entry(pattern, markers);
	}

	private static Marker parseMarker(JsonElement element)
	{
		if (!element.isJsonObject())
		{
			return null;
		}
		final JsonObject object = element.getAsJsonObject();
		final JsonElement percentage = object.get("percentage");
		final Color color = color(object.get("color"));
		if (percentage == null || !percentage.isJsonPrimitive() || !percentage.getAsJsonPrimitive().isNumber() || color == null)
		{
			return null;
		}
		final float fraction = percentage.getAsFloat();
		return fraction > 0f && fraction < 1f ? new Marker(fraction, color) : null;
	}

	// Usually a "#AARRGGBB" string, but an object holding the ARGB value if it was saved without a color
	// type adapter. The other plugin draws its lines opaque, so the alpha is dropped.
	private static Color color(JsonElement element)
	{
		if (element == null)
		{
			return null;
		}

		final String hex = string(element);
		if (hex != null)
		{
			final String digits = hex.startsWith("#") ? hex.substring(1) : hex;
			if (digits.length() != 6 && digits.length() != 8)
			{
				return null;
			}
			try
			{
				return new Color((int) Long.parseLong(digits, 16));
			}
			catch (NumberFormatException e)
			{
				return null;
			}
		}

		if (!element.isJsonObject())
		{
			return null;
		}
		final JsonElement value = element.getAsJsonObject().get("value");
		if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isNumber())
		{
			return null;
		}
		return new Color(value.getAsInt());
	}

	private static String string(JsonElement element)
	{
		return element != null && element.isJsonPrimitive() && element.getAsJsonPrimitive().isString()
			? element.getAsString() : null;
	}
}

package com.ghordrin.bosshealthbar;

import com.google.common.annotations.VisibleForTesting;
import com.google.common.collect.ImmutableMap;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.QuantityFormatter;
import net.runelite.client.util.Text;

// Reads the kill counts saved by RuneLite's Chat Commands plugin. It keys them by the boss name in the
// game's kill count message, lowercased, which is usually the NPC name.
@Singleton
class KillCounts
{
	static final String CONFIG_GROUP = "killcount";

	// Opponents whose kill count is saved under a different name, such as one count shared by several NPCs.
	@VisibleForTesting
	static final Map<String, String> KEYS = new ImmutableMap.Builder<String, String>()
		.put("dusk", "grotesque guardians")
		.put("dawn", "grotesque guardians")
		.put("ahrim the blighted", "barrows chests")
		.put("dharok the wretched", "barrows chests")
		.put("guthan the infested", "barrows chests")
		.put("karil the tainted", "barrows chests")
		.put("torag the corrupted", "barrows chests")
		.put("verac the defiled", "barrows chests")
		.put("blood moon", "lunar chest")
		.put("blue moon", "lunar chest")
		.put("eclipse moon", "lunar chest")
		.put("branda the fire queen", "royal titans")
		.put("eldric the ice king", "royal titans")
		.put("crystalline hunllef", "gauntlet")
		.put("corrupted hunllef", "corrupted gauntlet")
		.put("the nightmare", "nightmare")
		.put("the leviathan", "leviathan")
		.put("the whisperer", "whisperer")
		.put("the hueycoatl", "hueycoatl")
		.put("the mimic", "mimic")
		.put("judge of yama", "yama")
		.put("doom of mokhaiotl (shielded)", "doom of mokhaiotl")
		.put("doom of mokhaiotl (burrowed)", "doom of mokhaiotl")
		.build();

	private final ConfigManager configManager;

	private String cachedKey;
	private String cachedText;

	@Inject
	KillCounts(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	static String key(String name)
	{
		if (name == null)
		{
			return null;
		}
		final String lower = Text.removeTags(name).trim().toLowerCase(Locale.ROOT);
		// Other opponents could share a name with an unrelated saved count.
		if (lower.isEmpty() || !KnownBosses.contains(lower))
		{
			return null;
		}
		return KEYS.getOrDefault(lower, lower);
	}

	static String text(Integer count)
	{
		return count != null && count > 0 ? "KC " + QuantityFormatter.formatNumber(count.longValue()) : null;
	}

	void invalidate()
	{
		cachedKey = null;
		cachedText = null;
	}

	// Called every frame, so the result is kept for the last key.
	String textFor(String key)
	{
		if (key == null)
		{
			return null;
		}
		if (!key.equals(cachedKey))
		{
			cachedKey = key;
			cachedText = text(configManager.getRSProfileConfiguration(CONFIG_GROUP, key, int.class));
		}
		return cachedText;
	}
}

package com.ghordrin.bosshealthbar;

import java.awt.Color;
import net.runelite.api.gameval.SpriteID;

public enum HealthBarTheme implements BarTheme
{
	// GodWarsIcons has no named constants: _0 is Saradomin, _1 Zamorak, _2 Bandos and _3 Armadyl.
	SARADOMIN("Saradomin", 0x2F62C8, 0x1C3C84, 0xC9A54A, 0xF4F0E0, SpriteID.GodWarsIcons._0),
	ZAMORAK("Zamorak", 0xB01818, 0x6A0C0C, 0x5A4E4E, 0xF0A030, SpriteID.GodWarsIcons._1),
	GUTHIX("Guthix", 0x3E9A3A, 0x28602A, 0x8A7450, 0xE8DDB0),
	ARMADYL("Armadyl", 0xE2DED0, 0xA4A090, 0x6E8E9A, 0x7FD6E6, SpriteID.GodWarsIcons._3),
	BANDOS("Bandos", 0x7A8A3A, 0x5A4A26, 0x7A6448, 0xD0A870, SpriteID.GodWarsIcons._2),
	// Zaros has no God Wars icon, so it borrows an Ancient prayer icon.
	ZAROS("Zaros", 0x6E2AB0, 0x3E1670, 0x5A5068, 0xC080F0, SpriteID.IconPrayerZaros01_30x30.REJUVENATION),
	SEREN("Seren", 0x7ED8E6, 0x3E9CB8, 0xB8D4DA, 0xF2FCFF),
	TUMEKEN("Tumeken", 0xE0A82E, 0xB0701C, 0x3E5E9A, 0xFFF0C0),
	ELIDINIS("Elidinis", 0x2E9EA8, 0x1E6078, 0xB89A5A, 0xC8F0F0),
	RALOS("Ralos", 0xF08A1C, 0xC04818, 0xC09040, 0xFFE890),
	RANUL("Ranul", 0x8898C8, 0x4A5488, 0x9AA0B0, 0xE8ECF8),
	CUSTOM("Custom");

	private final String label;
	private final ThemeColors colors;
	private final Integer godIconSpriteId;

	HealthBarTheme(String label)
	{
		this.label = label;
		this.colors = null;
		this.godIconSpriteId = null;
	}

	HealthBarTheme(String label, int fillHigh, int fillLow, int frame, int trail)
	{
		this(label, fillHigh, fillLow, frame, trail, null);
	}

	HealthBarTheme(String label, int fillHigh, int fillLow, int frame, int trail, Integer godIconSpriteId)
	{
		this.label = label;
		this.godIconSpriteId = godIconSpriteId;
		this.colors = ThemeColors.of(new Color(fillHigh), new Color(fillLow), new Color(frame), new Color(trail));
	}

	static HealthBarTheme named(String name)
	{
		for (HealthBarTheme theme : values())
		{
			if (theme.name().equals(name))
			{
				return theme;
			}
		}
		return null;
	}

	@Override
	public boolean isFlat()
	{
		return false;
	}

	@Override
	public ThemeColors getColors()
	{
		return colors;
	}

	@Override
	public Integer getGodIconSpriteId()
	{
		return godIconSpriteId;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.ghordrin.bosshealthbar;

import java.util.List;

final class BarState
{
	static final float[] NO_PHASE_MARKERS = new float[0];

	final String name;
	final int combatLevel;
	final Integer maxHealth;
	final int ratio;
	final int scale;
	final boolean exactHealth;
	final boolean percentOnly;
	final float[] phaseMarkers;
	final HealthIndicatorMarkers.Marker[] userMarkers;
	final String killCountKey;
	final BossStats.Info stats;
	final List<SpecialAttackCounts.Reading> specialAttacks;

	BarState(String name, int combatLevel, Integer maxHealth, int ratio, int scale,
		boolean exactHealth, boolean percentOnly, float[] phaseMarkers, HealthIndicatorMarkers.Marker[] userMarkers,
		String killCountKey, BossStats.Info stats, List<SpecialAttackCounts.Reading> specialAttacks)
	{
		this.name = name;
		this.combatLevel = combatLevel;
		this.maxHealth = maxHealth;
		this.ratio = ratio;
		this.scale = scale;
		this.exactHealth = exactHealth;
		this.percentOnly = percentOnly;
		this.phaseMarkers = phaseMarkers;
		this.userMarkers = userMarkers;
		this.killCountKey = killCountKey;
		this.stats = stats;
		this.specialAttacks = specialAttacks;
	}
}

package com.ghordrin.bosshealthbar;

interface BarTheme
{
	static BarTheme of(BossHealthBarConfig config)
	{
		return effective(config.oldschoolTheme(), config.theme());
	}

	static BarTheme effective(boolean oldschool, HealthBarTheme dropdownTheme)
	{
		return oldschool ? FlatTheme.OLDSCHOOL : dropdownTheme;
	}

	// Null for the Custom theme, whose colors come from the config.
	ThemeColors getColors();

	Integer getGodIconSpriteId();

	// A flat theme has a plain fill and outline: no ornaments, crest, shine, texture, boss colors or gold bar.
	boolean isFlat();
}

package com.ghordrin.bosshealthbar;

import static com.ghordrin.bosshealthbar.BarAnimation.clamp01;
import static com.ghordrin.bosshealthbar.ColorUtil.brighten;
import static com.ghordrin.bosshealthbar.ColorUtil.darken;
import static com.ghordrin.bosshealthbar.ColorUtil.lerp;
import static com.ghordrin.bosshealthbar.ColorUtil.withAlpha;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.LinearGradientPaint;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.TexturePaint;
import java.awt.image.BufferedImage;
import java.time.Duration;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Consumer;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Texture;
import net.runelite.api.TextureProvider;

class BarPainter
{
	private static final Duration FLASH_DURATION = Duration.ofMillis(350);
	private static final float BIG_HIT_FRACTION = 0.08f;
	private static final int CAP_PLATE_WIDTH = 2;
	private static final int DIAMOND_RADIUS = 3;
	private static final int CAP_RISE = 3;
	private static final int CAP_REFERENCE_HEIGHT = 8;
	private static final float CAP_SCALE_PER_PIXEL = 0.09f;
	// Flat bars only need room for their outline, and for marker lines that stick out above and below.
	private static final int FLAT_EDGE = 1;
	private static final int FLAT_RISE = 2;
	// Cached images are drawn at twice their size and scaled down, so they stay sharp in stretched mode.
	static final float RASTER_SCALE = 2f;
	private static final int BAR_IMAGE_PAD = 8;

	private static final Color TRACK_TOP = new Color(6, 5, 5, 225);
	private static final Color TRACK_BOTTOM = new Color(26, 22, 22, 225);
	private static final Color HEAL_TINT = new Color(150, 235, 160);
	private static final Color BACKDROP = new Color(0, 0, 0, 34);
	private static final Color FRAME_OUTLINE = new Color(6, 5, 5);
	private static final Color DIAMOND_OUTLINE = new Color(6, 5, 5, 170);
	private static final Color TRACK_EDGE_SHADOW = new Color(0, 0, 0, 120);
	private static final Color MARKER_SHADOW = new Color(0, 0, 0, 170);
	private static final Color FLASH_COLOR = new Color(1f, 0.95f, 0.85f);
	private static final BasicStroke THIN_STROKE = new BasicStroke(1f);

	private final Client client;
	private final DamageTracker damageTracker;
	private final BossHealthBarConfig config;

	private ThemeColors derivedColorsSource;
	private Color healColor;
	private Color frameHighlightColor;
	private Color markerColor;

	private BufferedImage backdropImage;
	private BufferedImage endsImage;
	private int barImageWidth;
	private int barImageHeight;
	private Color barImageFrameColor;

	private final Map<Integer, BufferedImage> fillTextureCache = new HashMap<>();

	private BasicStroke frameStroke;
	private int frameStrokeHeight;

	@Inject
	BarPainter(Client client, DamageTracker damageTracker, BossHealthBarConfig config)
	{
		this.client = client;
		this.damageTracker = damageTracker;
		this.config = config;
	}

	void clearTextureCache()
	{
		fillTextureCache.clear();
	}

	private BasicStroke frameStroke(int height)
	{
		if (frameStroke == null || frameStrokeHeight != height)
		{
			frameStroke = new BasicStroke(scaledFrameStroke(height));
			frameStrokeHeight = height;
		}
		return frameStroke;
	}

	void drawBar(Graphics2D graphics, ThemeColors colors, BarState state, BarAnimation animation, boolean defeated,
		int y, int width, int height, float fillProgress, boolean useImageCache, boolean flat)
	{
		updateDerivedColors(colors);
		final float displayedFraction = animation.getDisplayedFraction();
		final float[] phaseMarkers = defeated ? BarState.NO_PHASE_MARKERS : state.phaseMarkers;
		final float lowHealthPulse = animation.lowHealthPulse(defeated, config.lowHealthEffect(), config.lowHealthThreshold());
		final Color frameColor = colors.getFrame();
		final int barX = capWidth(height, flat);
		final int barWidth = width - barX * 2;

		// The flat outline sits outside the bar, while the ornate frame is drawn on its edge.
		final int inset = flat ? 0 : 1;
		final int innerX = barX + inset;
		final int innerY = y + inset;
		final int innerWidth = barWidth - inset * 2;
		final int innerHeight = height - inset * 2;

		final Color baseFill = lerp(colors.getFillLow(), colors.getFillHigh(), clamp01(displayedFraction));
		final Color fill = lowHealthPulse > 0f ? brighten(baseFill, 0.55f * lowHealthPulse) : baseFill;
		final int fillWidth = Math.round(innerWidth * clamp01(displayedFraction) * fillProgress);

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		if (!flat)
		{
			if (useImageCache)
			{
				updateBarImages(width, height, frameColor);
				graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
				drawRasterImage(graphics, backdropImage, -BAR_IMAGE_PAD, y - BAR_IMAGE_PAD, width + BAR_IMAGE_PAD * 2, height + BAR_IMAGE_PAD * 2);
			}
			else
			{
				drawBackdrop(graphics, barX, y, barWidth, height);
			}
		}

		if (!flat && lowHealthPulse > 0f && fillWidth > 0)
		{
			final Color glow = brighten(baseFill, 0.2f);
			for (int i = 4; i >= 1; i--)
			{
				final int spread = i * 3;
				final int arc = height + spread * 2;
				graphics.setColor(withAlpha(glow, Math.round(lowHealthPulse * 130 / i)));
				graphics.fillRoundRect(innerX - spread, y - spread, fillWidth + spread * 2, height + spread * 2, arc, arc);
			}
		}

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);

		final Color track = colors.getTrack();
		graphics.setPaint(track != null ? track : new GradientPaint(0, y, TRACK_TOP, 0, y + height, TRACK_BOTTOM));
		graphics.fillRect(barX, y, barWidth, height);

		final float trailFraction = animation.getTrailFraction();
		if (config.showDamageTrail() && trailFraction > displayedFraction)
		{
			Color trail = colors.getTrail();
			int trailWidth = Math.round(innerWidth * clamp01(trailFraction) * fillProgress);
			graphics.setPaint(flat ? trail : verticalSheen(innerY, innerHeight, trail, 0.2f, 0.35f));
			graphics.fillRect(innerX, innerY, trailWidth, innerHeight);
		}

		final int healWidth = Math.round(innerWidth * clamp01(animation.getActualFraction()) * fillProgress);
		if (healWidth > fillWidth)
		{
			graphics.setPaint(flat ? healColor : verticalSheen(innerY, innerHeight, healColor, 0.35f, 0.3f));
			graphics.fillRect(innerX, innerY, healWidth, innerHeight);
		}

		if (fillWidth > 0)
		{
			graphics.setPaint(flat ? fill : verticalSheen(innerY, innerHeight, fill, 0.3f, 0.45f));
			graphics.fillRect(innerX, innerY, fillWidth, innerHeight);

			final BufferedImage fillTexture = flat ? null : resolveFillTexture();
			if (fillTexture != null)
			{
				final Composite textureComposite = graphics.getComposite();
				graphics.setPaint(new TexturePaint(fillTexture, new Rectangle(innerX, innerY, fillTexture.getWidth(), fillTexture.getHeight())));
				graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.35f));
				graphics.fillRect(innerX, innerY, fillWidth, innerHeight);
				graphics.setComposite(textureComposite);
			}

			if (!flat)
			{
				graphics.setColor(withAlpha(brighten(fill, 0.6f), 90));
				graphics.drawLine(innerX, innerY, innerX + fillWidth - 1, innerY);
			}
		}

		final int filledWidth = Math.max(fillWidth, healWidth);
		if (!flat && filledWidth < innerWidth)
		{
			graphics.setColor(TRACK_EDGE_SHADOW);
			graphics.drawLine(innerX + filledWidth, innerY, innerX + innerWidth - 1, innerY);
		}

		if (flat)
		{
			graphics.setStroke(THIN_STROKE);
			graphics.setColor(frameColor);
			graphics.drawRect(barX - 1, y - 1, barWidth + 1, height + 1);
		}
		else if (lowHealthPulse > 0f)
		{
			graphics.setStroke(frameStroke(height));
			final Color frame = lerp(frameColor, brighten(baseFill, 0.3f), 0.85f * lowHealthPulse);
			drawFrame(graphics, barX, y, barWidth, height, frame, withAlpha(brighten(frame, 0.35f), 120));
		}
		else
		{
			graphics.setStroke(frameStroke(height));
			drawFrame(graphics, barX, y, barWidth, height, frameColor, frameHighlightColor);
		}

		graphics.setStroke(THIN_STROKE);
		for (float marker : phaseMarkers)
		{
			final int markerX = innerX + Math.round((innerWidth - 1) * marker);
			graphics.setColor(MARKER_SHADOW);
			graphics.drawLine(markerX + 1, innerY, markerX + 1, innerY + innerHeight - 1);
			graphics.setColor(markerColor);
			graphics.drawLine(markerX, y - 2, markerX, y + height + 1);
		}

		if (!defeated)
		{
			for (HealthIndicatorMarkers.Marker marker : state.userMarkers)
			{
				final int markerX = innerX + Math.round((innerWidth - 1) * marker.getFraction());
				graphics.setColor(MARKER_SHADOW);
				graphics.drawLine(markerX + 1, innerY, markerX + 1, innerY + innerHeight - 1);
				graphics.setColor(marker.getColor());
				graphics.drawLine(markerX, y - 2, markerX, y + height + 1);
			}
		}

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		if (!flat)
		{
			if (useImageCache)
			{
				graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
				drawRasterImage(graphics, endsImage, -BAR_IMAGE_PAD, y - BAR_IMAGE_PAD, width + BAR_IMAGE_PAD * 2, height + BAR_IMAGE_PAD * 2);
			}
			else
			{
				drawEnds(graphics, barX, y, barWidth, height, frameColor);
			}
		}

		if (config.flashOnBigHits() && state.maxHealth != null)
		{
			final long lastHit = damageTracker.getLastHitMillis();
			if (lastHit != 0 && damageTracker.getLastHitAmount() >= state.maxHealth * BIG_HIT_FRACTION)
			{
				final long since = System.currentTimeMillis() - lastHit;
				if (since < FLASH_DURATION.toMillis())
				{
					float alpha = 1f - (since / (float) FLASH_DURATION.toMillis());
					graphics.setColor(withAlpha(FLASH_COLOR, Math.round(clamp01(alpha) * 0.8f * 255)));
					graphics.drawRect(barX, y, barWidth - 1, height - 1);
				}
			}
		}
	}

	private void updateDerivedColors(ThemeColors colors)
	{
		if (colors == derivedColorsSource)
		{
			return;
		}

		healColor = lerp(colors.getFillHigh(), HEAL_TINT, 0.45f);
		frameHighlightColor = withAlpha(brighten(colors.getFrame(), 0.35f), 120);
		markerColor = withAlpha(brighten(colors.getFrame(), 0.55f), 235);
		derivedColorsSource = colors;
	}

	private BufferedImage resolveFillTexture()
	{
		final int textureId = config.fillTextureId();
		if (textureId < 0)
		{
			return null;
		}

		final BufferedImage cached = fillTextureCache.get(textureId);
		if (cached != null)
		{
			return cached;
		}

		final TextureProvider textureProvider = client.getTextureProvider();
		if (textureProvider == null)
		{
			return null;
		}
		final Texture[] textures = textureProvider.getTextures();
		if (textureId >= textures.length || textures[textureId] == null)
		{
			return null;
		}
		final int[] pixels = textureProvider.load(textureId);
		if (pixels == null || pixels.length == 0)
		{
			return null;
		}
		final int side = (int) Math.round(Math.sqrt(pixels.length));
		if (side * side != pixels.length)
		{
			return null;
		}

		final BufferedImage image = new BufferedImage(side, side, BufferedImage.TYPE_INT_RGB);
		image.setRGB(0, 0, side, side, pixels, 0, side);
		fillTextureCache.put(textureId, image);
		return image;
	}

	static int capWidth(int barHeight, boolean flat)
	{
		return flat ? FLAT_EDGE : scaledCapWidth(barHeight);
	}

	static int capRise(int barHeight, boolean flat)
	{
		return flat ? FLAT_RISE : scaledCapRise(barHeight);
	}

	static float capScale(int barHeight)
	{
		return 1f + Math.max(0, barHeight - CAP_REFERENCE_HEIGHT) * CAP_SCALE_PER_PIXEL;
	}

	static int scaledCapPlateWidth(int barHeight)
	{
		return Math.round(CAP_PLATE_WIDTH * capScale(barHeight));
	}

	static int scaledDiamondRadius(int barHeight)
	{
		return Math.round(DIAMOND_RADIUS * capScale(barHeight));
	}

	static int scaledCapRise(int barHeight)
	{
		return Math.round(CAP_RISE * capScale(barHeight));
	}

	static int scaledCapWidth(int barHeight)
	{
		return scaledCapPlateWidth(barHeight) + scaledDiamondRadius(barHeight) * 2 + 2;
	}

	static float scaledFrameStroke(int barHeight)
	{
		return Math.max(1f, capScale(barHeight));
	}

	private static void drawFrame(Graphics2D graphics, int x, int y, int width, int height, Color frameColor,
		Color highlightColor)
	{
		graphics.setColor(FRAME_OUTLINE);
		graphics.drawRect(x - 1, y - 1, width + 1, height + 1);

		graphics.setColor(frameColor);
		graphics.drawRect(x, y, width - 1, height - 1);

		graphics.setColor(highlightColor);
		graphics.drawLine(x + 1, y, x + width - 2, y);
	}

	private void updateBarImages(int width, int height, Color frameColor)
	{
		if (backdropImage != null && width == barImageWidth && height == barImageHeight
			&& frameColor.equals(barImageFrameColor))
		{
			return;
		}

		final int barX = scaledCapWidth(height);
		final int barWidth = width - scaledCapWidth(height) * 2;
		backdropImage = barImage(width, height, g -> drawBackdrop(g, barX, BAR_IMAGE_PAD, barWidth, height));
		endsImage = barImage(width, height, g -> drawEnds(g, barX, BAR_IMAGE_PAD, barWidth, height, frameColor));
		barImageWidth = width;
		barImageHeight = height;
		barImageFrameColor = frameColor;
	}

	private static BufferedImage barImage(int width, int height, Consumer<Graphics2D> painter)
	{
		final int logicalWidth = width + BAR_IMAGE_PAD * 2;
		final int logicalHeight = height + BAR_IMAGE_PAD * 2;
		final BufferedImage image = new BufferedImage(Math.round(logicalWidth * RASTER_SCALE),
			Math.round(logicalHeight * RASTER_SCALE), BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.scale(RASTER_SCALE, RASTER_SCALE);
		g.translate(BAR_IMAGE_PAD, 0);
		painter.accept(g);
		g.dispose();
		return image;
	}

	static void drawRasterImage(Graphics2D graphics, BufferedImage image, int x, int y, int logicalWidth, int logicalHeight)
	{
		graphics.drawImage(image, x, y, x + logicalWidth, y + logicalHeight, 0, 0, image.getWidth(), image.getHeight(), null);
	}

	private static void drawBackdrop(Graphics2D graphics, int barX, int y, int barWidth, int height)
	{
		graphics.setColor(BACKDROP);
		for (int i = 3; i >= 1; i--)
		{
			graphics.fillRoundRect(barX - i * 2, y - i - 1, barWidth + i * 4, height + i * 2 + 2, height + i * 2, height + i * 2);
		}
	}

	private static void drawEnds(Graphics2D graphics, int barX, int y, int barWidth, int height, Color frameColor)
	{
		drawFinials(graphics, barX, y, barWidth, height, frameColor);
		drawUnderline(graphics, barX, y + height + 1, barWidth, frameColor);
	}

	private static LinearGradientPaint verticalSheen(int y, int height, Color base, float lift, float shade)
	{
		return new LinearGradientPaint(
			0, y, 0, y + Math.max(1, height),
			new float[]{0f, 0.45f, 1f},
			new Color[]{brighten(base, lift), base, darken(base, shade)});
	}

	private static void drawFinials(Graphics2D graphics, int barX, int y, int barWidth, int height, Color frameColor)
	{
		final int plateWidth = scaledCapPlateWidth(height);
		final int diamond = scaledDiamondRadius(height);
		final int top = y - scaledCapRise(height);
		final int bottom = y + height + scaledCapRise(height);
		final int midY = y + height / 2;
		final int rightEdge = barX + barWidth;

		graphics.setPaint(new GradientPaint(0, top, brighten(frameColor, 0.35f), 0, bottom, darken(frameColor, 0.35f)));
		graphics.fillRect(barX - plateWidth, top, plateWidth, bottom - top);
		graphics.fillRect(rightEdge, top, plateWidth, bottom - top);

		final int leftCx = barX - plateWidth - diamond - 1;
		final int rightCx = rightEdge + plateWidth + diamond + 1;
		final int[] ys = {midY - diamond, midY, midY + diamond, midY};
		final int[] leftXs = {leftCx, leftCx + diamond, leftCx, leftCx - diamond};
		final int[] rightXs = {rightCx, rightCx + diamond, rightCx, rightCx - diamond};
		graphics.fillPolygon(leftXs, ys, 4);
		graphics.fillPolygon(rightXs, ys, 4);

		graphics.setStroke(new BasicStroke(scaledFrameStroke(height)));
		graphics.setColor(DIAMOND_OUTLINE);
		graphics.drawPolygon(leftXs, ys, 4);
		graphics.drawPolygon(rightXs, ys, 4);

		graphics.setColor(withAlpha(brighten(frameColor, 0.7f), 200));
		graphics.fillRect(leftCx, midY - diamond + 1, 1, 1);
		graphics.fillRect(rightCx, midY - diamond + 1, 1, 1);
	}

	private static void drawUnderline(Graphics2D graphics, int barX, int y, int barWidth, Color frameColor)
	{
		graphics.setPaint(new LinearGradientPaint(
			barX, 0, barX + barWidth, 0,
			new float[]{0f, 0.5f, 1f},
			new Color[]{withAlpha(frameColor, 0), withAlpha(brighten(frameColor, 0.2f), 80), withAlpha(frameColor, 0)}));
		graphics.fillRect(barX, y + 1, barWidth, 1);
	}
}

package com.ghordrin.bosshealthbar;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

// Turns off the health bar of RuneLite's Opponent Information plugin while this plugin runs, and
// puts the user's own setting back afterwards.
@Singleton
class OpponentInfoOverride
{
	private static final String GROUP = "opponentinfo";
	private static final String KEY = "showOpponentHealthOverlay";
	// Stored in config so the original value can still be restored if the client closes while hidden.
	private static final String SAVED_KEY = "savedOpponentHealthOverlay";
	private static final String HIDDEN_KEY = "opponentHealthOverlayHidden";

	private final ConfigManager configManager;
	private final BossHealthBarConfig config;

	@Inject
	OpponentInfoOverride(ConfigManager configManager, BossHealthBarConfig config)
	{
		this.configManager = configManager;
		this.config = config;
	}

	void apply()
	{
		if (!config.hideVanillaOverlay())
		{
			return;
		}

		if (!isHidden())
		{
			final String current = configManager.getConfiguration(GROUP, KEY);
			if (current == null)
			{
				configManager.unsetConfiguration(BossHealthBarConfig.GROUP, SAVED_KEY);
			}
			else
			{
				configManager.setConfiguration(BossHealthBarConfig.GROUP, SAVED_KEY, current);
			}
			configManager.setConfiguration(BossHealthBarConfig.GROUP, HIDDEN_KEY, true);
		}

		configManager.setConfiguration(GROUP, KEY, false);
	}

	void restore()
	{
		if (!isHidden())
		{
			return;
		}

		final String saved = configManager.getConfiguration(BossHealthBarConfig.GROUP, SAVED_KEY);
		if (saved == null)
		{
			configManager.unsetConfiguration(GROUP, KEY);
		}
		else
		{
			configManager.setConfiguration(GROUP, KEY, saved);
		}

		configManager.unsetConfiguration(BossHealthBarConfig.GROUP, SAVED_KEY);
		configManager.unsetConfiguration(BossHealthBarConfig.GROUP, HIDDEN_KEY);
	}

	private boolean isHidden()
	{
		return Boolean.parseBoolean(configManager.getConfiguration(BossHealthBarConfig.GROUP, HIDDEN_KEY));
	}
}

package com.ghordrin.bosshealthbar;

import com.google.inject.Provides;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.GameState;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.NpcChanged;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PluginChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = BossHealthBarPlugin.NAME,
	description = "Replaces the opponent health bar with a themed bar that shows a damage trail and your recent damage",
	tags = {"boss", "health", "healthbar", "hitpoints", "overlay", "pvm", "combat", "ui", "theme"}
)
public class BossHealthBarPlugin extends Plugin
{
	static final String NAME = "Boss Health Bar Additions";

	@Inject
	private ClientThread clientThread;

	@Inject
	private BossHealthBarConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BossHealthBarOverlay overlay;

	@Inject
	private OpponentTracker opponentTracker;

	@Inject
	private GameBossBar gameBossBar;

	@Inject
	private TobBossBar tobBossBar;

	@Inject
	private SuperiorTracker superiorTracker;

	@Inject
	private DamageTracker damageTracker;

	@Inject
	private OpponentInfoOverride opponentInfoOverride;

	@Inject
	private CustomColors customColors;

	@Inject
	private Pickers pickers;

	@Inject
	private HealthIndicatorMarkers healthIndicatorMarkers;

	@Inject
	private PartyDamage partyDamage;

	@Inject
	private KillCounts killCounts;

	@Inject
	private PartyDefence partyDefence;

	@Inject
	private SpecialAttackCounts specialAttackCounts;

	@Provides
	BossHealthBarConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BossHealthBarConfig.class);
	}

	@Override
	protected void startUp()
	{
		migrateReplaceNativeBossBar();
		overlay.reset();
		healthIndicatorMarkers.invalidate();
		killCounts.invalidate();
		partyDefence.reset();
		specialAttackCounts.reset();
		partyDamage.startUp();
		overlayManager.add(overlay);
		opponentInfoOverride.apply();
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		partyDamage.shutDown();
		opponentInfoOverride.restore();
		pickers.close();
		clientThread.invoke(() ->
		{
			gameBossBar.restore();
			tobBossBar.restore();
			resetState();
		});
	}

	private void migrateReplaceNativeBossBar()
	{
		final String oldSaved = configManager.getConfiguration(
			BossHealthBarConfig.GROUP, BossHealthBarConfig.OLD_REPLACE_NATIVE_BOSS_BAR_KEY);
		if (oldSaved == null)
		{
			return;
		}

		final NativeBossBarMode mode = NativeBossBarMode.migrate(oldSaved,
			configManager.getConfiguration(BossHealthBarConfig.GROUP, BossHealthBarConfig.NATIVE_BOSS_BAR_MODE_KEY));
		if (mode != null)
		{
			configManager.setConfiguration(BossHealthBarConfig.GROUP, BossHealthBarConfig.NATIVE_BOSS_BAR_MODE_KEY, mode);
		}
		configManager.unsetConfiguration(BossHealthBarConfig.GROUP, BossHealthBarConfig.OLD_REPLACE_NATIVE_BOSS_BAR_KEY);
	}

	// Reset can walk the settings in any order, so put these back to their defaults once it's done.
	@Override
	public void resetConfiguration()
	{
		applyWrites(OldschoolToggle.resetWrites());
	}

	private void applyOldschoolToggle(String key, boolean oldValue, boolean newValue)
	{
		applyWrites(OldschoolToggle.writes(key, oldValue, newValue,
			new OldschoolToggle.Settings(config.oldschoolTheme(), config.matchBossColors(), config.rareGoldBars(),
				savedBoolean(BossHealthBarConfig.SAVED_MATCH_BOSS_COLORS_KEY),
				savedBoolean(BossHealthBarConfig.SAVED_RARE_GOLD_BARS_KEY))));
	}

	private void applyWrites(List<OldschoolToggle.Write> writes)
	{
		// Each write posts its own change event straight away. Handling those again is harmless, since
		// the remembered keys are cleared before anything is turned back on.
		for (OldschoolToggle.Write write : writes)
		{
			if (write.getValue() == null)
			{
				configManager.unsetConfiguration(BossHealthBarConfig.GROUP, write.getKey());
			}
			else
			{
				configManager.setConfiguration(BossHealthBarConfig.GROUP, write.getKey(), write.getValue());
			}
		}
	}

	private Boolean savedBoolean(String key)
	{
		final String saved = configManager.getConfiguration(BossHealthBarConfig.GROUP, key);
		return saved != null ? Boolean.valueOf(saved) : null;
	}

	private static boolean parseBoolean(String value, boolean defaultValue)
	{
		return value != null ? Boolean.parseBoolean(value) : defaultValue;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			resetState();
		}
	}

	private void resetState()
	{
		gameBossBar.reset();
		tobBossBar.reset();
		superiorTracker.reset();
		opponentTracker.reset();
		damageTracker.reset();
		killCounts.invalidate();
		partyDefence.reset();
		specialAttackCounts.reset();
		overlay.reset();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (HealthIndicatorMarkers.CONFIG_GROUP.equals(event.getGroup()))
		{
			clientThread.invoke(healthIndicatorMarkers::invalidate);
			return;
		}

		if (KillCounts.CONFIG_GROUP.equals(event.getGroup()))
		{
			clientThread.invoke(killCounts::invalidate);
			return;
		}

		if (!BossHealthBarConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		overlay.invalidateColors();

		if (BossHealthBarConfig.THEME_KEY.equals(event.getKey())
			&& HealthBarTheme.CUSTOM.name().equals(event.getNewValue()))
		{
			customColors.copyFrom(event.getOldValue());
		}

		if (OldschoolToggle.handles(event.getKey()))
		{
			final boolean defaultValue = BossHealthBarConfig.RARE_GOLD_BARS_KEY.equals(event.getKey());
			applyOldschoolToggle(event.getKey(), parseBoolean(event.getOldValue(), defaultValue),
				parseBoolean(event.getNewValue(), defaultValue));
		}

		// The config screen has no buttons, so these two checkboxes act as one: ticking opens the
		// picker and the tick is undone straight away.
		if (BossHealthBarConfig.CHOOSE_FILL_TEXTURE_KEY.equals(event.getKey()) && "true".equals(event.getNewValue()))
		{
			configManager.setConfiguration(BossHealthBarConfig.GROUP, BossHealthBarConfig.CHOOSE_FILL_TEXTURE_KEY, false);
			pickers.openFillTexturePicker();
		}

		if (BossHealthBarConfig.CHOOSE_CUSTOM_ICON_KEY.equals(event.getKey()) && "true".equals(event.getNewValue()))
		{
			configManager.setConfiguration(BossHealthBarConfig.GROUP, BossHealthBarConfig.CHOOSE_CUSTOM_ICON_KEY, false);
			pickers.openIconPickerIfLoggedIn();
		}

		if (BossHealthBarConfig.HIDE_VANILLA_OVERLAY_KEY.equals(event.getKey()))
		{
			if (config.hideVanillaOverlay())
			{
				opponentInfoOverride.apply();
			}
			else
			{
				opponentInfoOverride.restore();
			}
		}
	}

	@Subscribe
	public void onPluginChanged(PluginChanged event)
	{
		clientThread.invoke(() ->
		{
			healthIndicatorMarkers.invalidate();
			partyDefence.invalidatePlugin();
			specialAttackCounts.invalidatePlugin();
		});
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		clientThread.invoke(killCounts::invalidate);
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		opponentTracker.onInteractingChanged(event);
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		opponentTracker.onHitsplatApplied(event.getActor(), event.getHitsplat());
		if (event.getActor() == opponentTracker.getOpponent())
		{
			final Hitsplat hitsplat = event.getHitsplat();
			damageTracker.recordHit(hitsplat, config.damageNumberSource());
			if (hitsplat.isMine() && hitsplat.getHitsplatType() != HitsplatID.HEAL)
			{
				partyDamage.sendHit(event.getActor(), hitsplat.getAmount());
			}
		}
	}

	@Subscribe
	public void onBossBarPartyHit(BossBarPartyHit event)
	{
		clientThread.invoke(() -> partyDamage.onPartyHit(event));
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		gameBossBar.onNpcSpawned();
		tobBossBar.onNpcSpawned(event.getNpc());
		superiorTracker.onNpcSpawned(event.getNpc());
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event)
	{
		tobBossBar.onNpcChanged(event.getNpc());
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		gameBossBar.onNpcDespawned(event.getNpc());
		tobBossBar.onNpcDespawned(event.getNpc());
		superiorTracker.onNpcDespawned(event.getNpc());
		opponentTracker.onNpcDespawned(event.getNpc());
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		superiorTracker.onChatMessage(event);
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		tobBossBar.onGameTick();
		superiorTracker.onGameTick();
		opponentTracker.onGameTick();
		partyDefence.update(opponentTracker.getOpponent());
		specialAttackCounts.update(opponentTracker.getOpponent());
	}

	// Runs every frame because the game's scripts can unhide their bars whenever they update.
	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		opponentTracker.followGameBars();

		final Actor opponent = opponentTracker.getOpponent();
		final boolean replace = config.nativeBossBarMode().hidesGameBar();
		final boolean opponentGetsBar = opponentTracker.shouldShowBarFor(opponent);
		gameBossBar.update(opponent, replace, opponentGetsBar);
		tobBossBar.update(opponent, replace, opponentGetsBar);
	}
}

package com.ghordrin.bosshealthbar;

import static com.ghordrin.bosshealthbar.ColorUtil.brighten;
import java.awt.Color;
import lombok.Builder;
import lombok.Value;

@Value
@Builder(toBuilder = true)
class ThemeColors
{
	static final Color DEFAULT_TEXT = new Color(0xE8E2D4);
	static final Color DEFAULT_HITPOINTS_TEXT = new Color(0xC8C0B0);
	private static final float MIN_TRAIL_CONTRAST = 1.5f;

	Color fillHigh;
	Color fillLow;
	Color trail;
	// Plain color behind the fill. Null keeps the default dark track.
	Color track;

	Color frame;

	Color text;
	Color levelText;
	Color hitpointsText;
	Color defeatedText;

	static ThemeColors of(Color fillHigh, Color fillLow, Color frame, Color trail)
	{
		return ThemeColors.builder()
			.fillHigh(fillHigh)
			.fillLow(fillLow)
			.trail(trail)
			.frame(frame)
			.text(DEFAULT_TEXT)
			.levelText(brighten(frame, 0.35f))
			.hitpointsText(DEFAULT_HITPOINTS_TEXT)
			.defeatedText(brighten(frame, 0.45f))
			.build();
	}

	// Follows how the built-in themes relate their colors: a darker fill at low health that leans red
	// for warm colors, a pale trail of the same hue, and a dark frame tinted with it.
	static ThemeColors fromBase(Color base)
	{
		final float[] hsb = Color.RGBtoHSB(base.getRed(), base.getGreen(), base.getBlue(), null);
		final float hue = hsb[0];
		final float saturation = hsb[1];
		final boolean grey = saturation < 0.12f;
		final boolean warm = hue >= 20f / 360f && hue <= 80f / 360f;

		final Color fillLow = Color.getHSBColor(hue + (warm ? -10f : 5f) / 360f,
			grey ? saturation : Math.min(1f, saturation * 1.03f + (saturation < 0.5f ? 0.14f : 0f)),
			hsb[2] * 0.68f);
		Color trail = Color.getHSBColor(hue, Math.min(0.5f, saturation * 0.4f), 0.97f);
		if (contrast(trail, base) < MIN_TRAIL_CONTRAST)
		{
			trail = Color.getHSBColor(hue + 0.5f, 0.45f, 0.9f);
		}
		final Color frame = Color.getHSBColor(hue, grey ? 0.06f : 0.2f, 0.45f);
		return of(base, fillLow, frame, trail);
	}

	static float contrast(Color a, Color b)
	{
		final float la = luminance(a);
		final float lb = luminance(b);
		return (Math.max(la, lb) + 0.05f) / (Math.min(la, lb) + 0.05f);
	}

	private static float luminance(Color c)
	{
		return 0.2126f * linear(c.getRed()) + 0.7152f * linear(c.getGreen()) + 0.0722f * linear(c.getBlue());
	}

	private static float linear(int channel)
	{
		final float c = channel / 255f;
		return c <= 0.03928f ? c / 12.92f : (float) Math.pow((c + 0.055f) / 1.055f, 2.4f);
	}
}

package com.ghordrin.bosshealthbar;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.chatbox.ChatboxItemSearch;

// Opens the custom icon search and the fill texture window.
@Singleton
class Pickers
{
	private final Client client;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final BossHealthBarConfig config;
	private final ChatboxItemSearch itemSearch;

	// Only touched on the EDT.
	private FillTexturePickerDialog texturePickerDialog;

	@Inject
	Pickers(Client client, ClientThread clientThread, ConfigManager configManager, BossHealthBarConfig config,
		ChatboxItemSearch itemSearch)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.config = config;
		this.itemSearch = itemSearch;
	}

	// Must be called on the client thread.
	void openIconPicker()
	{
		itemSearch
			.tooltipText("Custom icon")
			.onItemSelected(itemId -> configManager.setConfiguration(
				BossHealthBarConfig.GROUP, BossHealthBarConfig.CUSTOM_ICON_ITEM_ID_KEY, itemId))
			.build();
	}

	// The item search lives in the chatbox, so it only opens while logged in.
	void openIconPickerIfLoggedIn()
	{
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				openIconPicker();
			}
		});
	}

	void openFillTexturePicker()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (texturePickerDialog == null || !texturePickerDialog.isDisplayable())
			{
				texturePickerDialog = new FillTexturePickerDialog(client, clientThread, configManager, config);
			}
			texturePickerDialog.setVisible(true);
			texturePickerDialog.toFront();
		});
	}

	void close()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (texturePickerDialog != null)
			{
				texturePickerDialog.dispose();
				texturePickerDialog = null;
			}
		});
	}
}

